  /** A kind allows for different kinds of variables to be treated differently depending on what they are used for. A refless kind indicates that it's just a plain variable and we can not derive possible values from it A datadog kind indicates that we will use the ref value as a lookup against a datadog tag */
  kind: DashboardVariableKind;
  name: string;
  /** The ref value indicates where this variable can derive its values from */
  ref?: string;
  /** Values is an indication of possible values for this variable, it may not be all the possible values just known quantities */
